附件-7 路径代价计算 

由于各种汽车的颜色在装配线上的组合形式多样，使用路径搜索算法给出的可能路径
非常多。以下采用Matlab 计算各种路径的代价，并且取代价最小的路径填入装配顺序的整
个过程中去，程序文件名称“pathsCost.m”，具体见数据文件夹。 

function [minCost,opt_paths]=pathsCost(paths,config,color,num,c) 
%paths：需要验证的所有路径 
%config：汽车配置 
%color：汽车颜色 
%num：对应的汽车数量 
%c：起始点处的喷涂线分配 
%miniCost：最小代价 
%opt_paths：最小代价对应的所有最优路径 
 N=sum(num); 
 idx=zeros(N,1); %用来记录每个顶点的属性类表序号 
 s=1; 
 for k = 1:length(num) 
 idx(s:(s+num(k)-1))=k; 
 s=s+num(k); 
 end 
 maxpath=size(paths,1); 
 Cost = zeros(maxpath,1); 
 for k=1:maxpath 
 path = paths(k,1:end-1); 
 Cost0 = 0; 
 for t = 1:N 
 if t>=2 
 if ~strcmp(config{idx(t)},config{idx(t-1)}) 
 %装配线上配置改变代价+1 
 Cost0 = Cost0+1; 
 end 
 end 
 if t>=3 
 if ~strcmp(color{idx(t)},color{idx(t-2)}) 
 %喷涂线上颜色改变代价+1 
 Cost0 = Cost0+1; 
 end 
 end 
 %金色汽车喷绘线为C2 
 if strcmp(color{idx(t)},'金') 
 if (c == 1 && mod(t,2) == 1) || (c == 2 && mod(t,2) == 0) 
 Cost0 = Cost0+100000; 
 end 
 end 
 %黄、蓝、红色汽车喷绘线为C1 
 if strcmp(color{idx(t)},'黄') || strcmp(color{idx(t)},'蓝') || strcmp(color{idx(t)},'红') 
 if (c == 1 && mod(t,2) == 0) || (c == 2 && mod(t,2) == 1) 
 Cost0 = Cost0+100000; 
 end 
 end 
 end 
 Cost(k) = Cost0; 
 end 
 minCost = min(Cost); 
 mink = Cost==minCost; 
 opt_paths=paths(mink,1:end-1);
